INSERT INTO `tag` (`name`, `status`) SELECT 'Mobile Photography', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Mobile Photography') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'CASL', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'CASL') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'SkillsFuture', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'SkillsFuture') x);

